/* ---------- eventos */
var PT={},arr=null,pin=null,mov=0;
palco.addEventListener('pointerdown',function(e){if(e.target.closest('.wlt-ctl'))return;PT[e.pointerId]={x:e.clientX,y:e.clientY};
  if(Object.keys(PT).length==1){arr={x:e.clientX,y:e.clientY,a:A,b:B,id:e.pointerId};mov=0}
  else{var k=Object.keys(PT),p1=PT[k[0]],p2=PT[k[1]];pin={d:Math.abs(p1.x-p2.x)||1,a:A,b:B,cx:(p1.x+p2.x)/2-palco.getBoundingClientRect().left};arr=null}
});
